def load() -> pd.DataFrame:
    with open('data/wildfire/input/nifc_wildfires.csv', 'r') as f:
        lines = [f.readline() for _ in range(10)]
    return pd.DataFrame({'raw_lines': lines})

def process(noaa_annual) -> pd.DataFrame:
    df = noaa_annual[noaa_annual['Year'] <= 2024].copy()
    return df

def process(nifc_clean, noaa_clean) -> pd.DataFrame:
    nifc_avg = nifc_clean['Fires'].mean()
    noaa_avg = noaa_clean['Fires'].mean()
    difference = round(noaa_avg - nifc_avg)

    return pd.DataFrame({
        'NIFC_Avg': [nifc_avg],
        'NOAA_Avg': [noaa_avg],
        'Difference': [difference]
    })

def process(nifc_clean, noaa_clean):
    merged = nifc_clean.merge(noaa_clean, on='Year', suffixes=('_nifc', '_noaa'))
    merged['difference'] = merged['Fires_noaa'] - merged['Fires_nifc']
    return merged.head(10)
